class Solution:
    def minimizedMaximum(self, n: int, quantities: list[int]) -> int:
        # find the max number 
        # f(x)
        def canDistribute(x: int) -> bool:
            numOfStore = 0
            for q in quantities:
                numOfStore += math.ceil(q / x)

            return numOfStore <= n 

        total = sum(quantities)
        if total < n:
            return 1

        lo, hi = 1, max(quantities)
        ans = hi
        while lo <= hi:
            mid = (lo + hi) // 2

            if canDistribute(mid):
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return ans
